  site: string;
  date: string;
  concentrationPciL: number;
};

export function weeklySummary(readings: RadonReading[]) {
  const counts = new Map<string, { normal: number; outOfRange: number }>();
  for (const reading of readings) {
    const siteCounts = counts.get(reading.site) ?? { normal: 0, outOfRange: 0 };
    if (reading.concentrationPciL > 4) siteCounts.outOfRange += 1;
    else siteCounts.normal += 1;
    counts.set(reading.site, siteCounts);
  }
  return [...counts].map(([site, value]) => ({ site, ...value }));
}

