import sys


def differing_files(left, right):
    left_root = Path(left)
    right_root = Path(right)
    return [
        path.relative_to(left_root).as_posix()
        for path in left_root.rglob("*")
        if path.is_file()
        and path.read_bytes() != (right_root / path.relative_to(left_root)).read_bytes()
    ]


if __name__ == "__main__":
    print("\n".join(differing_files(sys.argv[1], sys.argv[2])))

