"""Point-of-sale change helper."""

def make_change(amount: int, denominations: list[int]) -> dict[int, int]:
    """Return change using a largest-first pass."""
    result = {}
    for value in sorted(denominations, reverse=True):
        count, amount = divmod(amount, value)
        if count:
            result[value] = count
    if amount:
        raise ValueError("cannot make exact change")
    return result

