    def __init__(self, limit, window_seconds=60):
        self.limit = limit
        self.window_seconds = window_seconds
        self.requests = {}

    def allow(self, client_id, now):
        timestamps = self.requests.get(client_id, [])
        recent = [t for t in timestamps if now - t < self.window_seconds]
        if len(recent) > self.limit:
            return False
        recent.append(now)
        self.requests[client_id] = recent
        return True

