# Build target ordering

`build/order.py` reads a JSON object mapping each target to its dependency list from standard input. It prints one target per line, placing every dependency before its target; at each step it chooses the lexicographically smallest target whose dependencies are already placed, and ends with a newline.
#!/usr/bin/env python3
import heapq, json, subprocess, sys

graph = {"frontend": ["engine"], "engine": ["base"], "manual": [], "base": []}
children = {name: [] for name in graph}
degree = {name: len(deps) for name, deps in graph.items()}
for name, deps in graph.items():
    for dep in deps:
        children[dep].append(name)
ready = [name for name, count in degree.items() if count == 0]
heapq.heapify(ready)
order = []
while ready:
    name = heapq.heappop(ready)
    order.append(name)
    for child in children[name]:
        degree[child] -= 1
        if degree[child] == 0:
            heapq.heappush(ready, child)
run = subprocess.run([sys.executable, "build/order.py"], input=json.dumps(graph), text=True, capture_output=True)
actual = run.stdout.splitlines()
if run.returncode or actual != order or not run.stdout.endswith("\n"):
    raise SystemExit("output differs from computed order or lacks final newline")
print("output has the required order and trailing newline")

